  "offline.held.visit.cancelled": "ನಿಮ್ಮ ಕೆಲಸ ಕಳುಹಿಸುವ ಮೊದಲೇ ECCS ಈ ವಿಸಿಟ್ ರದ್ದುಮಾಡಿದೆ, ಹಾಗಾಗಿ ಅದನ್ನು ಕಳುಹಿಸಿಲ್ಲ. ಅದು ಇನ್ನೂ ಈ ಫೋನ್‌ನಲ್ಲಿದೆ. ಏನನ್ನಾದರೂ ಅಳಿಸುವ ಮೊದಲು ECCS ಆಫೀಸ್‌ಗೆ ಕಾಲ್ ಮಾಡಿ. ಈ ಫೋನ್‌ನಲ್ಲಿ ಇಟ್ಟಿರುವುದು: {count}",
