  "plan.changeHelp": "ಬದಲಾವಣೆ ನಿಮ್ಮ ಮುಂದಿನ ಅವಧಿಯಿಂದ, ಅಂದರೆ {date} ರಿಂದ ಶುರುವಾಗುತ್ತದೆ. ಅಲ್ಲಿಯವರೆಗೆ ನಿಮ್ಮ ಪ್ಲಾನ್ ಈಗಿರುವಂತೆಯೇ ಇರುತ್ತದೆ, ಮತ್ತು ಇಂದು ಯಾವ ಹಣವೂ ಕಟ್ಟಬೇಕಿಲ್ಲ.",
  "plan.changeTo": "{plan} ಗೆ ಬದಲಾಯಿಸಿ",
  "plan.changeConfirm": "{date} ರಂದು {plan} ಗೆ ಬದಲಾಯಿಸಬೇಕೇ?\n\nಅಲ್ಲಿಯವರೆಗೆ ನಿಮ್ಮ ಪ್ಲಾನ್ {current} ಆಗಿಯೇ ಇರುತ್ತದೆ; ಅದಕ್ಕೆ ಈಗಾಗಲೇ ಇನ್‌ವಾಯ್ಸ್ ಕೊಡಲಾಗಿದೆ.\n\n{date} ರಿಂದ ನೀವು GST ಸೇರಿ {price} ಪಾವತಿಸುತ್ತೀರಿ, ಮತ್ತು {plan} ನ ಸರ್ವಿಸ್‌ಗಳು ಸಿಗುತ್ತವೆ. {plan} ನಲ್ಲಿ ಇಲ್ಲದ ಸರ್ವಿಸ್‌ಗಳು ಅದೇ ದಿನ ನಿಲ್ಲುತ್ತವೆ.\n\n{date} ವರೆಗೆ ನೀವು ಈ ಬದಲಾವಣೆಯನ್ನು ವಾಪಸ್ ಪಡೆಯಬಹುದು.",
  "plan.changeYes": "ಪ್ಲಾನ್ ಬದಲಾಯಿಸಿ",
  "plan.changeNo": "{plan} ಅನ್ನೇ ಇಟ್ಟುಕೊಳ್ಳಿ",
  "plan.changeSaved": "ನೀವು {date} ರಂದು {plan} ಗೆ ಬದಲಾಗುತ್ತೀರಿ",
