  "plan.changeUndone": "ನೀವು {plan} ಪ್ಲಾನ್‌ನಲ್ಲೇ ಮುಂದುವರಿಯುತ್ತೀರಿ",
  "plan.noOther": "ಸದ್ಯಕ್ಕೆ ಬದಲಾಯಿಸಲು ಬೇರೆ ಪ್ಲಾನ್ ಇಲ್ಲ.",
  "plan.closeChange": "ಪ್ಲಾನ್‌ಗಳ ಪಟ್ಟಿ ಮುಚ್ಚಿ",
  "plan.cancel": "ಪ್ಲಾನ್ ರದ್ದುಮಾಡಿ",
  "plan.cancelConfirm": "{plan} ಪ್ಲಾನ್ ರದ್ದುಮಾಡಬೇಕೇ?\n\nನಿಮ್ಮ ವಿಸಿಟ್‌ಗಳು {date} ವರೆಗೆ, ಅಂದರೆ ಈಗಾಗಲೇ ಇನ್‌ವಾಯ್ಸ್ ಕೊಟ್ಟಿರುವ ಅವಧಿಯ ಕೊನೆಯವರೆಗೆ ಮುಂದುವರಿಯುತ್ತವೆ.\n\n{date} ನಂತರ ಪ್ಲಾನ್ ರಿನ್ಯೂ ಆಗುವುದಿಲ್ಲ, ಹೊಸ ಇನ್‌ವಾಯ್ಸ್ ಯಾವುದೂ ಬರುವುದಿಲ್ಲ, ಮತ್ತು ಆ ದಿನದ ನಂತರಕ್ಕೆ ಪ್ಲಾನ್ ಮಾಡಿದ್ದ ವಿಸಿಟ್‌ಗಳನ್ನು ನಿಮ್ಮ ಡೈರಿಯಿಂದ ತೆಗೆಯಲಾಗುತ್ತದೆ.\n\n{date} ವರೆಗೆ ನೀವು ಇದನ್ನು ವಾಪಸ್ ಪಡೆಯಬಹುದು.",
  "plan.cancelConfirmNow": "{plan} ಪ್ಲಾನ್ ರದ್ದುಮಾಡಬೇಕೇ?\n\nಇದು ಇಂದೇ ಮುಗಿಯುತ್ತದೆ. ಇನ್ನೂ ಶುರುವಾಗದ ಇದರ ವಿಸಿಟ್‌ಗಳನ್ನು ನಿಮ್ಮ ಡೈರಿಯಿಂದ ತೆಗೆಯಲಾಗುತ್ತದೆ, ಮತ್ತು ಹೊಸ ಇನ್‌ವಾಯ್ಸ್ ಯಾವುದೂ ಬರುವುದಿಲ್ಲ.\n\nಇದನ್ನು ವಾಪಸ್ ಪಡೆಯಲು ಆಗುವುದಿಲ್ಲ, ಆದರೆ ನೀವು ಮತ್ತೆ ಪ್ಲಾನ್ ತೆಗೆದುಕೊಳ್ಳಬಹುದು.",
