  "push.ask.title": "ತಕ್ಷಣ ತಿಳಿಸಬೇಕೇ?",
  "push.ask.body": "ನೀವು ಗಮನಿಸಬೇಕಾದದ್ದು ಏನಾದರೂ ಇದ್ದಾಗ ECCS ಈ ಫೋನ್‌ನಲ್ಲಿ ನೋಟಿಫಿಕೇಶನ್ ತೋರಿಸಬಹುದು: ವಿಸಿಟ್ ಮುಗಿದಿದೆ, ECCS ಉತ್ತರಿಸಿದೆ, ಚೆಕ್‌ಲಿಸ್ಟ್ ಸಮಯ ಮೀರಿದೆ, ಲೈಸೆನ್ಸ್ ಅವಧಿ ಮುಗಿಯುತ್ತಿದೆ. ನೋಡಲು ನೀವು ಮತ್ತೆ ಮತ್ತೆ ಆ್ಯಪ್ ತೆರೆಯಬೇಕಾಗಿಲ್ಲ.",
