  "push.status.off": "ಈ ಫೋನ್‌ನಲ್ಲಿ ನೋಟಿಫಿಕೇಶನ್‌ಗಳು ಆಫ್ ಆಗಿವೆ. ಹೊಸವು ನೀವು ಆ್ಯಪ್ ತೆರೆದಾಗ ಮಾತ್ರ ಕಾಣಿಸುತ್ತವೆ.",
  "push.status.blocked": "ಈ ಫೋನ್‌ನ ಸೆಟ್ಟಿಂಗ್ಸ್‌ನಲ್ಲಿ ECCS ನೋಟಿಫಿಕೇಶನ್‌ಗಳನ್ನು ಬ್ಲಾಕ್ ಮಾಡಲಾಗಿದೆ. ತಕ್ಷಣ ತಿಳಿಯಲು ಅಲ್ಲಿ ಅವುಗಳಿಗೆ ಅನುಮತಿ ಕೊಡಿ.",
