  "public.how.2": "ಪ್ರತಿ ಅಂಶ ಪಾಲನೆ ಆಗಿದೆಯೇ ಇಲ್ಲವೇ ಎಂದು ಗುರುತು ಮಾಡಲಾಗುತ್ತದೆ. ಸಿಗಬಹುದಾದ ಒಟ್ಟು ಅಂಕಗಳಲ್ಲಿ ಸಿಕ್ಕ ಅಂಕಗಳನ್ನು 100 ರಲ್ಲಿ ಒಂದು ಸಂಖ್ಯೆಯಾಗಿ ತೋರಿಸುವುದೇ ಸ್ಕೋರ್. ಗಂಭೀರ ಅಪಾಯಕ್ಕೆ ಸಂಬಂಧಿಸಿದ ಅಂಶಗಳನ್ನು ಎರಡು ಪಟ್ಟು ಲೆಕ್ಕ ಹಾಕಲಾಗುತ್ತದೆ.",
  "public.how.3": "ಗ್ರೇಡ್ A+ ಎಂದರೆ {aPlus} ಅಥವಾ ಹೆಚ್ಚು, A ಎಂದರೆ {a} ಅಥವಾ ಹೆಚ್ಚು, B ಎಂದರೆ {b} ಅಥವಾ ಹೆಚ್ಚು. {b} ಕ್ಕಿಂತ ಕಡಿಮೆ ಇದ್ದರೆ, ಅಥವಾ ಗಂಭೀರ ಅಪಾಯಕ್ಕೆ ಸಂಬಂಧಿಸಿದ ಯಾವುದೇ ಒಂದು ಅಂಶ ಪಾಲನೆ ಆಗದಿದ್ದರೆ, ಗ್ರೇಡ್ ಕೊಡುವುದಿಲ್ಲ.",
  "public.how.4": "ಪ್ರತಿ ರಿಪೋರ್ಟ್ ಇಲ್ಲಿ ಕಾಣಿಸುವ ಮೊದಲು ECCS ಆಫೀಸ್ ಅದನ್ನು ಅನುಮೋದಿಸುತ್ತದೆ. ಫಲಿತಾಂಶವನ್ನು {days} ದಿನ ತೋರಿಸಲಾಗುತ್ತದೆ, ನಂತರ ಮುಂದಿನ ತಪಾಸಣೆಯವರೆಗೆ ಈ ಪೇಜ್‌ನಿಂದ ತೆಗೆಯಲಾಗುತ್ತದೆ.",
  "public.not.heading": "ಇದರಲ್ಲಿ ಏನು ಸೇರಿಲ್ಲ",
  "public.not.2": "ಆಹಾರದ ರುಚಿ ಅಥವಾ ಗುಣಮಟ್ಟ, ಸರ್ವಿಸ್ ಅಥವಾ ಊಟ ಮಾಡುವ ಜಾಗದ ಬಗ್ಗೆ ಇದು ಏನನ್ನೂ ಹೇಳುವುದಿಲ್ಲ.",
  "public.not.3": "ಆಹಾರ ನಿಮಗೆ ಸುರಕ್ಷಿತ ಎಂಬ ಭರವಸೆ ಇದಲ್ಲ. ನಿಮಗೆ ಅಲರ್ಜಿ ಇದ್ದರೆ ಸ್ಟಾಫ್ ಅನ್ನು ಕೇಳಿ.",
  "public.gov.heading": "ಇದು ಸರ್ಕಾರಿ ರೇಟಿಂಗ್ ಅಲ್ಲ",
  "public.gov.check": "ಪ್ರತಿ ರೆಸ್ಟೋರೆಂಟ್ ತನ್ನ FSSAI ಲೈಸೆನ್ಸ್ ಅನ್ನು ಎಲ್ಲರಿಗೂ ಕಾಣುವಂತೆ ಇಡಬೇಕು. FSSAI ನ ಸ್ವಂತ ವೆಬ್‌ಸೈಟ್ (foscos.fssai.gov.in) ನಲ್ಲಿ ಅಥವಾ ಅದರ Food Safety Connect ಆ್ಯಪ್‌ನಲ್ಲಿ ನೀವು ಲೈಸೆನ್ಸ್ ಪರಿಶೀಲಿಸಬಹುದು ಅಥವಾ ದೂರು ಕೊಡಬಹುದು.",
  "public.updated": "ಪೇಜ್ ಕೊನೆಯದಾಗಿ {date} ರಂದು {time} ಕ್ಕೆ ಅಪ್‌ಡೇಟ್ ಆಗಿದೆ.",
