  "face.consent.what": "ಈಗ ನಿಮ್ಮ ಮುಖದ ಕೆಲವು ಫೋಟೋಗಳನ್ನು ತೆಗೆದು, ಅವುಗಳನ್ನು ಮುಖದ ಮಾದರಿಯಾಗಿ (ಸಂಖ್ಯೆಗಳ ಒಂದು ಪಟ್ಟಿ) ಬದಲಾಯಿಸಲಾಗುತ್ತದೆ. ಈ ಫೋಟೋಗಳನ್ನು ಇಟ್ಟುಕೊಳ್ಳುವುದಿಲ್ಲ. ನೀವು ಪ್ರತಿ ಸಲ ಕ್ಲಾಕ್ ಇನ್ ಅಥವಾ ಕ್ಲಾಕ್ ಔಟ್ ಮಾಡುವಾಗ ಒಂದು ಫೋಟೋ ತೆಗೆಯಲಾಗುತ್ತದೆ. ಓನರ್ ಮತ್ತು ಮ್ಯಾನೇಜರ್ ಪರಿಶೀಲಿಸಲು ಆಗುವಂತೆ ಅದನ್ನು {days} ದಿನ ಇಟ್ಟುಕೊಂಡು, ಆಮೇಲೆ ಅಳಿಸಲಾಗುತ್ತದೆ.",

